#include <bits/stdc++.h>
using namespace std;

pair<int, int> findCenter(const vector<vector<int>>& graph) {
    auto bfs = [&](int start) {
        vector<int> dist(graph.size(), -1);
        queue<int> q;
        q.push(start);
        dist[start] = 0;
        int farthest = start;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            if (dist[u] > dist[farthest]) farthest = u;

            for (int v : graph[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return pair<int, vector<int>>(farthest, move(dist));
    };

    int endpointA = bfs(0).first;
    auto [endpointB, distA] = bfs(endpointA);
    auto [unused, distB] = bfs(endpointB);

    int center = 0;
    for (int i = 1; i < (int)graph.size(); ++i) {
        if (max(distA[i], distB[i]) < max(distA[center], distB[center])) {
            center = i;
        }
    }
    return {center, endpointB};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> circle(N), square(M);

    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        circle[a].push_back(b);
        circle[b].push_back(a);
    }

    for (int i = 0; i < M - 1; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        square[x].push_back(y);
        square[y].push_back(x);
    }

    int circleCenter = findCenter(circle).first;
    int squareCenter = findCenter(square).first;

    cout << circleCenter + 1 << ' ' << squareCenter + 1 << '\n';
    return 0;
}
